/* Token Radar's dashboard: a dark radar board. One palette, one type scale, no network. */
:root {
  --bg: #0a0f1c;
  --panel: #101a2e;
  --panel-2: #0d1526;
  --line: #1e2c47;
  --text: #e8eef7;
  --muted: #93a4bd;
  --faint: #64748b;
  --accent: #2dd4a7;
  --accent-dim: #123f33;
  --blue: #38bdf8;
  --amber: #fbbf24;
  --red: #f87171;
  --radius: 12px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.skip { position: absolute; left: -9999px; top: 0; background: var(--accent); color: #04120c; padding: 8px 14px; border-radius: 0 0 8px 0; font-weight: 700; }
.skip:focus { left: 0; }
a { color: var(--blue); }
.shell { max-width: 1160px; margin: 0 auto; padding: 20px 20px 48px; }
.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
.sub { color: var(--muted); font-size: 13px; }
.pos { color: var(--accent); }
.neg { color: var(--red); }

/* Header */
.top { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; padding: 6px 0 18px; border-bottom: 1px solid var(--line); }
.brand { display: flex; align-items: center; gap: 10px; font-size: 19px; font-weight: 800; letter-spacing: -0.01em; }
.mark { width: 30px; height: 30px; border-radius: 50%; border: 2px solid var(--accent); position: relative; flex: none; }
.mark::before { content: ""; position: absolute; inset: 5px; border-radius: 50%; background: var(--accent); opacity: 0.85; }
.mark::after { content: ""; position: absolute; inset: -2px; border-radius: 50%; border: 2px solid transparent; border-top-color: var(--accent); animation: spin 6s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.top-meta { display: flex; flex-wrap: wrap; gap: 8px; }
.top-meta span { background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: 4px 11px; font-size: 12.5px; color: var(--muted); }

/* Lede + facts */
.lede { display: grid; grid-template-columns: 1.5fr 1fr; gap: 20px; padding: 22px 0 6px; }
.lede h1 { margin: 0 0 8px; font-size: 27px; line-height: 1.25; letter-spacing: -0.02em; }
.lede p { margin: 0; color: var(--muted); max-width: 62ch; }
.lede p b { color: var(--text); }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 14px; }
.fact span { display: block; font-size: 12px; color: var(--muted); margin-bottom: 3px; }
.fact b { font-size: 20px; font-variant-numeric: tabular-nums; }
.fact b em { font-style: normal; color: var(--accent); }

/* Spotlight */
.spot { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 18px 0 6px; }
.spot-card { background: linear-gradient(160deg, #12233d, var(--panel)); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; cursor: pointer; text-align: left; color: var(--text); font: inherit; }
.spot-card:hover, .spot-card:focus-visible { border-color: var(--accent); outline: none; }
.spot-card .rank-tag { display: inline-block; font-size: 11.5px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #04120c; background: var(--accent); border-radius: 999px; padding: 2px 9px; }
.spot-card h3 { margin: 9px 0 2px; font-size: 17px; }
.spot-card .implied { font-size: 22px; font-weight: 800; color: var(--accent); font-variant-numeric: tabular-nums; }
.spot-card .meta { color: var(--muted); font-size: 13px; margin-top: 4px; }

/* Controls */
.controls { display: flex; flex-wrap: wrap; gap: 14px; align-items: flex-end; margin: 16px 0 14px; }
.field label, .field .sub { display: block; font-size: 12px; color: var(--muted); margin-bottom: 5px; }
.field input[type="search"], .field select {
  background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 8px;
  padding: 8px 11px; font: inherit; font-size: 14px; min-width: 280px;
}
.field input[type="search"]:focus, .field select:focus { outline: 2px solid var(--accent); outline-offset: 1px; border-color: var(--accent); }
.tabs { display: flex; gap: 6px; }
.tabs button {
  background: var(--panel); color: var(--muted); border: 1px solid var(--line); border-radius: 999px;
  padding: 7px 15px; font: inherit; font-size: 13.5px; font-weight: 650; cursor: pointer;
}
.tabs button[aria-pressed="true"] { background: var(--accent-dim); color: var(--accent); border-color: var(--accent); }
.count { margin-left: auto; align-self: center; color: var(--muted); font-size: 13px; }

/* Table */
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: 12px 16px 0; color: var(--muted); font-size: 13px; }
thead th { text-align: left; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; padding: 12px 14px 8px; border-bottom: 1px solid var(--line); white-space: nowrap; }
thead th button { background: none; border: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; padding: 0; }
thead th button:hover { color: var(--text); }
tbody td { padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr:focus-visible { background: #152238; outline: none; }
tbody tr[data-selected="true"] { background: #132a24; }
.name b { display: block; font-size: 14.5px; }
.name .sub { display: block; margin-top: 1px; }
.implied { min-width: 150px; }
.bar { height: 6px; background: #1b2942; border-radius: 99px; overflow: hidden; margin-bottom: 5px; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, #1d9e7d, var(--accent)); border-radius: 99px; }
.status { display: inline-block; font-size: 12px; font-weight: 650; color: var(--amber); background: rgba(251, 191, 36, 0.1); border: 1px solid rgba(251, 191, 36, 0.35); border-radius: 999px; padding: 2px 9px; white-space: nowrap; }
.status.live { color: var(--blue); background: rgba(56, 189, 248, 0.1); border-color: rgba(56, 189, 248, 0.35); }
.empty { padding: 36px 24px; text-align: center; }
.empty h2 { margin: 0 0 6px; }
.empty p { color: var(--muted); margin: 0 0 16px; }
.button { background: var(--accent); color: #04120c; border: 0; border-radius: 8px; padding: 9px 16px; font: inherit; font-weight: 700; cursor: pointer; }

/* Model panel */
.model { margin-top: 16px; padding: 18px 20px; }
.model h2 { margin: 0 0 6px; font-size: 17px; }
.model p { margin: 0 0 10px; }
.formula { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 13px; line-height: 1.6; overflow-x: auto; white-space: nowrap; margin-bottom: 12px; }
.formula b { color: var(--accent); font-weight: 700; }
.model-note { font-size: 13px; color: var(--muted); }
.model-note b { color: var(--text); }

/* Detail dialog */
dialog.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 14px; padding: 0; width: min(680px, 94vw); max-height: 94vh; overflow-y: auto; }
dialog.detail::backdrop { background: rgba(3, 7, 18, 0.72); }
.detail-head { display: flex; justify-content: space-between; gap: 16px; padding: 18px 22px 0; }
.detail-head .brand-name { color: var(--accent); font-size: 12.5px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase; }
.detail-head h2 { margin: 5px 0 2px; font-size: 22px; }
.close { background: var(--panel-2); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 7px 13px; font: inherit; cursor: pointer; height: fit-content; }
.close:hover { border-color: var(--accent); }
.detail-section { padding: 13px 22px 15px; border-top: 1px solid var(--line); margin-top: 13px; }
.detail-section:first-of-type { border-top: 0; margin-top: 0; }
.detail-section h3 { margin: 0 0 10px; font-size: 15px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 20px; }
.equation > div { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px dashed var(--line); }
.equation span { color: var(--muted); font-size: 13.5px; }
.equation b { font-variant-numeric: tabular-nums; }
.equation .total { grid-column: 1 / -1; border-bottom: 0; }
.equation .total b { color: var(--accent); font-size: 17px; }
.steps { margin: 0; padding-left: 20px; }
.steps li { margin-bottom: 8px; }
.steps li b { font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
.check { font-size: 13px; color: var(--muted); margin: 10px 0 0; }
.check b { color: var(--accent); }

footer { margin-top: 22px; color: var(--faint); font-size: 12.5px; }
footer p { margin: 4px 0; }

@media (max-width: 760px) {
  .lede { grid-template-columns: 1fr; }
  .spot { grid-template-columns: 1fr; }
  .equation { grid-template-columns: 1fr; }
  .count { margin-left: 0; }
}
